//! Actual original Engine/Timeline integration, not a fake service Authority.
use mycity_core::{assembly,housing,service_delivery_authority::{Command as D,Motion},timeline::Command as T,transaction::{Action,Caller,Engine,Envelope}};
use serde_json::{json,Value};use std::{fs,path::PathBuf};
#[path="../../../tests/fixtures/service-delivery/opening.rs"]mod fixture;
fn root()->PathBuf{let p=PathBuf::from(std::env::var_os("MYCITY_SERVICE_DELIVERY_ROOT").expect("retained SSD root")).canonicalize().unwrap();assert!(p.starts_with("/Volumes/HP P900/dev/MyCity/work"));p}
fn apply(e:&mut Engine,p:&std::path::Path,op:&mut u64,caller:Caller,action:Action){let(scope,rev)=e.world().scope_revision();let req=Envelope{world:scope.world(),branch:scope.branch(),operation_id:*op,expected_revision:rev,actions:vec![action]};*op+=1;let out=e.execute(caller,req.clone());fs::write(p.join(format!("operation-{}.json",req.operation_id)),serde_json::to_vec_pretty(&json!({"request":req,"result":format!("{out:?}")})).unwrap()).unwrap();assert!(out.is_ok(),"{out:?}");}
fn advance(e:&mut Engine,p:&std::path::Path,op:&mut u64,target:u64){for _ in 0..256{let t=e.timeline().unwrap().progress;if t.target.is_none()&&t.last_complete==target{return;}apply(e,p,op,Caller::System,Action::Timeline{command:T::Advance{target,limit:256}});}panic!("bounded timeline did not finish");}
fn setup(p:&std::path::Path)->(Engine,u64){let mut e=fixture::engine();let mut op=1;apply(&mut e,p,&mut op,Caller::System,Action::Timeline{command:T::Enable});let raw=fixture::input();let offer:housing::GenesisLeaseOffer=serde_json::from_value(raw["housing"]["lease_offers"][0].clone()).unwrap();apply(&mut e,p,&mut op,Caller::Account(2),Action::HousingLease{offer_id:901,offer_sha256:housing::genesis_lease_offer_sha256(offer)});advance(&mut e,p,&mut op,28800);let n=e.service_needs_summary().unwrap();assert!(n.households[0].current[1].is_waiting());apply(&mut e,p,&mut op,Caller::Account(3),Action::ServiceDelivery{command:D::Accept{household:7,crew:1}});(e,op)}
fn view(e:&Engine)->mycity_core::service_delivery_authority::View{e.service_needs_summary().unwrap().delivery.unwrap()}
#[test]fn original_need_actual_edges_inputs_wages_and_safe_return_are_real(){let p=root().join(format!("flow-{}",std::process::id()));fs::create_dir(&p).unwrap();fs::write(p.join("opening.json"),serde_json::to_vec_pretty(&fixture::input()).unwrap()).unwrap();let(mut e,mut op)=setup(&p);
 for(at,motion,energy,work)in[(29100,Motion::Outbound,0,0),(29220,Motion::Outbound,6000,0),(29400,Motion::OnSite,15000,0),(33000,Motion::Returning,15000,3600),(33300,Motion::Reset,30000,3600),(33900,Motion::Finished,30000,3600)]{
  advance(&mut e,&p,&mut op,at);let v=view(&e);fs::write(p.join(format!("state-{at}.json")),serde_json::to_vec_pretty(&v).unwrap()).unwrap();assert_eq!(v.trips[0].motion,motion);assert_eq!(v.trips[0].drive_energy_mwh,energy);assert_eq!(v.tasks[0].work_seconds,work);
  if at<29400{assert!(v.tasks[0].arrival_at.is_none());}fs::write(p.join(format!("checkpoint-{at}.json")),e.export_checkpoint().unwrap()).unwrap();
 }
 let v=view(&e);assert_eq!(v.trips[0].fee_paid,2000);assert_eq!(v.trips[0].wages_paid,[1700,1700,0,0]);let world=e.world().view();assert_eq!(world.stocks.iter().find(|s|s.id==991).unwrap().quantity.value(),70000);assert_eq!(world.stocks.iter().find(|s|s.id==992).unwrap().quantity.value(),10000);assert_eq!(v.trips[0].energy_basis_cents,1300);assert_eq!(v.trips[0].water_basis_cents,100);assert!(e.leases().iter().all(Option::is_none));assert!(e.resources().iter().all(|r|r.occupied==0&&r.reserved==0));fs::write(p.join("final-world.json"),serde_json::to_vec_pretty(&world).unwrap()).unwrap();}
